// vendor/setup.sh: --check passes on the real vendor folder, and every hash mismatch is refused without touching what exists.
// The refusal tests use a temporary VD and stop at the offline steps (rows, kit), so they need no network.
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, symlinkSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { describe, test } from "node:test";
import { SKIP, VD, sha, tmp } from "./support.mjs";
import { TK } from "./make-fake-audit.mjs";

const SETUP = join(TK, "vendor", "setup.sh");
const setup = (args, env = {}) => spawnSync("bash", [SETUP, ...args], { encoding: "utf8", env: { PATH: process.env.PATH, HOME: process.env.HOME, ...env } });
const B77 = join(VD, "rows", "banking77-selected-rows.jsonl");
const CLINC = join(VD, "rows", "clinc-selected-rows.jsonl");

describe("vendor/setup.sh", { skip: SKIP }, () => {
  test("--check on the real vendor folder: all five parts verified, nothing written", () => {
    const before = readFileSync(join(VD, "venv-freeze.txt"), "utf8");
    const r = setup(["--check"], { DPROOF_VD: VD });
    assert.equal(r.status, 0, r.stderr);
    for (const part of [/rows\/banking77-selected-rows\.jsonl ok \(1629c6fb/, /rows\/clinc-selected-rows\.jsonl ok \(a0fbb6a5/, /kit ok \(87d4650b42b377c0291a89c1f1a879f9b31082bf/, /venv ok/, /bench ok \(@juspay\/neurolink 12\.47\.0\)/, /all pins verified/]) assert.match(r.stdout, part);
    assert.equal(readFileSync(join(VD, "venv-freeze.txt"), "utf8"), before);
  });

  test("the pins in the vendor folder are the contract's", () => {
    assert.equal(sha(readFileSync(B77)), "1629c6fbd0e2f60c9d5cfa1a67a9370af651b52e45b167ad15b08becba81782a");
    assert.equal(sha(readFileSync(CLINC)), "a0fbb6a532983860df2d782b54756d9294fe3267433401fb498b239173273435");
    assert.equal(sha(readFileSync(join(VD, "kit", "decision_index", "runner.py"))), "f4c9f36c4c557f537f1d8184db7bf00c5a84d9f4f0aa67f8c06198cead25818d");
    assert.equal(spawnSync("git", ["-C", join(VD, "kit"), "rev-parse", "HEAD"], { encoding: "utf8" }).stdout.trim(), "87d4650b42b377c0291a89c1f1a879f9b31082bf");
    assert.equal(JSON.parse(readFileSync(join(VD, "bench", "node_modules", "@juspay", "neurolink", "package.json"), "utf8")).version, "12.47.0");
  });

  test("--check on an empty folder is refused", () => {
    const r = setup(["--check"], { DPROOF_VD: tmp("empty-vd") });
    assert.equal(r.status, 1);
    assert.match(r.stderr, /REFUSED.*is missing/);
  });

  test("a rows source with another hash is refused and nothing is copied", () => {
    const vd = tmp("vd-bad-src");
    const bad = join(tmp("bad-src"), "rows.jsonl");
    writeFileSync(bad, "{}\n");
    const r = setup([], { DPROOF_VD: vd, DPROOF_ROWS_SRC_BANKING77: bad, DPROOF_ROWS_SRC_CLINC: CLINC });
    assert.equal(r.status, 1);
    assert.match(r.stderr, /REFUSED: source .* has a different sha256 than the pinned 1629c6fb/);
    assert.equal(existsSync(join(vd, "rows", "banking77-selected-rows.jsonl")), false);
  });

  test("an existing rows file with another hash is refused and left as it is", () => {
    const vd = tmp("vd-bad-dst");
    mkdirSync(join(vd, "rows"));
    writeFileSync(join(vd, "rows", "banking77-selected-rows.jsonl"), "someone edited this\n");
    const r = setup(["--check"], { DPROOF_VD: vd });
    assert.equal(r.status, 1);
    assert.match(r.stderr, /exists but its sha256 is not the pinned/);
    assert.equal(readFileSync(join(vd, "rows", "banking77-selected-rows.jsonl"), "utf8"), "someone edited this\n");
  });

  test("a kit source without the pinned commit is refused", () => {
    const vd = tmp("vd-bad-kit");
    mkdirSync(join(vd, "rows"));
    symlinkSync(B77, join(vd, "rows", "banking77-selected-rows.jsonl"));
    symlinkSync(CLINC, join(vd, "rows", "clinc-selected-rows.jsonl"));
    const src = tmp("kit-src");
    const git = (...args) => spawnSync("git", ["-C", src, "-c", "user.email=t@example.com", "-c", "user.name=t", ...args], { encoding: "utf8" });
    git("init", "-q");
    writeFileSync(join(src, "README"), "not the kit\n");
    git("add", ".");
    git("commit", "-q", "-m", "x");
    const r = setup([], { DPROOF_VD: vd, DPROOF_KIT_SRC: src });
    assert.equal(r.status, 1);
    assert.match(r.stderr, /does not contain the pinned commit/);
    assert.equal(existsSync(join(vd, "kit")), false, "no half-made kit folder is left");
  });

  test("a kit checkout whose runner.py or HEAD differs is refused", () => {
    const vd = tmp("vd-edited-kit");
    mkdirSync(join(vd, "rows"));
    symlinkSync(B77, join(vd, "rows", "banking77-selected-rows.jsonl"));
    symlinkSync(CLINC, join(vd, "rows", "clinc-selected-rows.jsonl"));
    assert.equal(spawnSync("git", ["clone", "-q", "--no-hardlinks", join(VD, "kit"), join(vd, "kit")]).status, 0);
    const runner = join(vd, "kit", "decision_index", "runner.py");
    writeFileSync(runner, `${readFileSync(runner, "utf8")}# edited\n`);
    const r = setup(["--check"], { DPROOF_VD: vd });
    assert.equal(r.status, 1);
    assert.match(r.stderr, /runner\.py does not hash to the pinned/);
  });
});

// Helpers for the runner tests: throwaway audit folders that use the fake provider and the fixture rows, `proof` child processes,
// and process listings. Nothing here reads a real env file or talks beyond 127.0.0.1.
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { homedir, tmpdir } from "node:os";
import { join } from "node:path";
import { gunzipSync } from "node:zlib";
import { fixtureConfig, pickRows, runProof, writeFakeEnvFiles } from "./make-fake-audit.mjs";

export { runProof };
export const VD = join(process.env.DPROOF_VD ?? join(homedir(), ".cache", "decide-proof"));
export const HAVE_VENDOR = ["kit/.git", "venv/bin/python", "bench/node_modules/@juspay/neurolink/package.json", "rows/banking77-selected-rows.jsonl", "rows/clinc-selected-rows.jsonl"].every((p) => existsSync(join(VD, p)));
export const SKIP = HAVE_VENDOR ? false : `vendor folder ${VD} is incomplete (run vendor/setup.sh)`;
export const LIVE = Object.freeze({ DPROOF_LIVE: "yes", DPROOF_FULL: "yes" });

export const sha = (bytes) => createHash("sha256").update(bytes).digest("hex");
export const tmp = (label) => mkdtempSync(join(tmpdir(), `dproof-rt-${label}-`));

// a throwaway audit: config + rows in a temp folder; fakePort is the fake provider's port
export const makeAudit = ({ port, caps = {}, maskPlanted, patch } = {}) => {
  const ad = tmp("ad");
  mkdirSync(join(ad, "rows"));
  const env = writeFakeEnvFiles();
  const picked = pickRows(VD);
  const rowsFiles = { banking77: join(ad, "rows", "b77.jsonl"), clinc: join(ad, "rows", "clinc.jsonl") };
  const rowsSha = {};
  for (const b of Object.keys(rowsFiles)) {
    writeFileSync(rowsFiles[b], `${picked[b].join("\n")}\n`);
    rowsSha[b] = sha(readFileSync(rowsFiles[b]));
  }
  let config = fixtureConfig({ ad, rowsFiles, rowsSha, port, envFiles: [env.main, env.paid], caps, ...(maskPlanted ? { maskPlanted } : {}) });
  if (patch) config = patch(config);
  const configPath = join(ad, "audit-config.json");
  writeFileSync(configPath, `${JSON.stringify(config, null, 2)}\n`);
  return { ad, configPath, config, rowsFiles };
};

export const runArgs = (a, { route = "luna", bench = "banking77", stage = "probe", extra = [] } = {}) => [
  "run", "--audit", a.configPath, "--audit-dir", a.ad, "--vd", VD, "--route", route, "--bench", bench, "--stage", stage, ...extra,
];

export const stageDir = (a, route = "luna", bench = "banking77", stage = "probe") => join(a.ad, "runs", route, bench, stage);

export const readGz = (path) => gunzipSync(readFileSync(path)).toString("utf8").split("\n").filter(Boolean).map((l) => JSON.parse(l));
export const readJson = (path) => JSON.parse(readFileSync(path, "utf8"));
export const readLines = (path) => readFileSync(path, "utf8").split("\n").filter(Boolean).map((l) => JSON.parse(l));

// processes whose command line mentions a marker (the runner's scratch folders are named dproof-run-*)
export const processesMatching = (marker) => {
  const out = execFileSync("ps", ["-ax", "-o", "pid=,command="], { encoding: "utf8" });
  return out.split("\n").filter((l) => l.includes(marker) && !l.includes("ps -ax"));
};

// Small child program for process-level recorder tests, run with `node --import TK/lib/recorder.mjs child.mjs`.
// DPROOF_TEST_MODE: fetch (one POST to DPROOF_TEST_URL, then end), crash (fetch, then throw), wait (fetch, print ready, wait for a signal),
// inactive (print what the recorder module reports without any DPROOF_REC_* setting).
const mode = process.env.DPROOF_TEST_MODE ?? "fetch";
const recorder = await import(process.env.DPROOF_TEST_RECORDER);

if (mode === "inactive") {
  process.stdout.write(`${JSON.stringify({ active: recorder.isActive(), seq: recorder.nextDecideSeq(), native: globalThis.fetch.name === "fetch" })}\n`);
  process.exit(0);
}

const r = await fetch(process.env.DPROOF_TEST_URL, {
  method: "POST",
  headers: { authorization: `Bearer ${process.env.CHILD_API_KEY}`, "content-type": "application/json" },
  body: JSON.stringify({ model: "m", state: {}, questions: { q1: { type: "choice", instructions: "hi", criteria: { option_0: "a", option_1: "b" } } } }),
});
await r.text();
if (mode === "crash") throw new Error("planned crash");
if (mode === "wait") {
  process.stdout.write("ready\n");
  setInterval(() => {}, 1000);
}

// Shared helpers for the tests in tests/lib: temp folders, reading recordings, running node children with a clean
// environment, and an independent recount of wire records (it does not import lib/money.mjs or lib/recorder.mjs).
import { spawn } from "node:child_process";
import { existsSync, mkdtempSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { gunzipSync } from "node:zlib";

export const TK = resolve(dirname(fileURLToPath(import.meta.url)), "../../..");
export const RECORDER = join(TK, "lib/recorder.mjs");
export const DRIVER = join(TK, "tests/lib/support/driver.mjs");
export const NEUROLINK_DIR =
  process.env.DPROOF_NEUROLINK_DIR ??
  "~/scratchpad/bench/node_modules/@juspay/neurolink";
export const NEUROLINK_ENTRY = join(NEUROLINK_DIR, "dist/index.js");
export const HAVE_NEUROLINK = existsSync(NEUROLINK_ENTRY);

export const tmp = (label) => mkdtempSync(join(tmpdir(), `dproof-${label}-`));

export const readJsonl = (path) =>
  readFileSync(path)
    .toString("utf8")
    .split("\n")
    .filter(Boolean)
    .map((l) => JSON.parse(l));

// records of DIR/<base>.jsonl.gz, or of the plain .jsonl when the gz does not exist
export const readRecords = (dir, base) => {
  const gz = join(dir, `${base}.jsonl.gz`);
  if (existsSync(gz)) {
    return gunzipSync(readFileSync(gz))
      .toString("utf8")
      .split("\n")
      .filter(Boolean)
      .map((l) => JSON.parse(l));
  }
  return readJsonl(join(dir, `${base}.jsonl`));
};

// A clean environment: no credentials, no proxy, an empty HOME so nothing reads the real ~/.neurolink.
export const cleanEnv = (extra = {}) => ({ PATH: process.env.PATH, HOME: tmp("home"), DOTENV_CONFIG_PATH: "/dev/null", NO_COLOR: "1", ...extra });

export const runNode = (args, { env, cwd = tmp("cwd"), timeoutMs = 120000 } = {}) =>
  new Promise((resolveRun) => {
    const child = spawn(process.execPath, args, { env, cwd, stdio: ["ignore", "pipe", "pipe"] });
    let stdout = "";
    let stderr = "";
    child.stdout.on("data", (d) => (stdout += d));
    child.stderr.on("data", (d) => (stderr += d));
    const timer = setTimeout(() => child.kill("SIGKILL"), timeoutMs);
    child.on("close", (code, signal) => {
      clearTimeout(timer);
      resolveRun({ code, signal, stdout, stderr });
    });
  });

// decimal string of tokens x price, price in USD per million tokens with at most 6 decimals; exact, in picodollars
const microOf = (price) => {
  const [whole, frac = ""] = price.split(".");
  return BigInt(whole + frac.padEnd(6, "0"));
};
const fmt = (pico) => {
  const whole = pico / 1000000000000n;
  const frac = (pico % 1000000000000n).toString().padStart(12, "0").replace(/0+$/, "");
  return frac ? `${whole}.${frac}` : `${whole}`;
};

// Recount books.json from the wire records alone.
export const recount = (wire, { priceIn, priceOut }) => {
  const pin = microOf(priceIn);
  const pout = microOf(priceOut);
  const sent = wire.filter((r) => !r.blocked);
  const statuses = {};
  let input = 0;
  let output = 0;
  let estimated = 0;
  let estimatedInput = 0;
  let cost = 0n;
  let usageCost = 0n;
  let network = 0;
  for (const r of sent) {
    if (r.response) statuses[String(r.response.status)] = (statuses[String(r.response.status)] ?? 0) + 1;
    else network++;
    const body = r.response?.body;
    const u = body?.usage ?? body?.result?.usage;
    const i = u ? (u.input_tokens ?? u.prompt_tokens) : undefined;
    if (Number.isInteger(i)) {
      const o = u.output_tokens ?? u.completion_tokens ?? 0;
      input += i;
      output += o;
      const c = BigInt(i) * pin + BigInt(o) * pout;
      usageCost += c;
      cost += c;
    } else {
      const est = Math.ceil(r.request.body_bytes / 2);
      estimated++;
      estimatedInput += est;
      cost += BigInt(est) * pin;
    }
  }
  const ids = new Set(sent.filter((r) => r.decide_seq !== null).map((r) => r.decide_seq));
  return {
    attempts: sent.length,
    records: wire.length,
    requests: ids.size + sent.filter((r) => r.decide_seq === null).length,
    input_tokens: input,
    output_tokens: output,
    estimated_attempts: estimated,
    estimated_input_tokens: estimatedInput,
    cost_usd: fmt(cost),
    cost_usd_from_usage: fmt(usageCost),
    status_counts: Object.fromEntries(Object.entries(statuses).sort((a, b) => Number(a[0]) - Number(b[0]))),
    network_errors: network,
    blocked: wire.filter((r) => r.blocked).length,
  };
};

// Test driver: stands in for the shim. Run as `node --import TK/lib/recorder.mjs driver.mjs` with DPROOF_TEST_PLAN set.
// For each planned call it does what the real shim does: startDecide, a real NeuroLink 12.47.0 decide() inside runInDecide,
// then writeDecide. One JSON line per call goes to stdout (no secrets: provider kind and status only).
// plan: { neurolinkEntry, recorderUrl, calls: [{ provider, model, env?, state, questions, timeoutMs, warmup? }], crashAfter? }
const plan = JSON.parse(process.env.DPROOF_TEST_PLAN);
const recorder = await import(plan.recorderUrl);
const { NeuroLink } = await import(plan.neurolinkEntry);
const neurolink = new NeuroLink();

for (const [i, call] of plan.calls.entries()) {
  for (const [k, v] of Object.entries(call.env ?? {})) process.env[k] = v;
  const handle = recorder.startDecide({ warmup: Boolean(call.warmup) });
  const kitRequest = JSON.stringify({ model: call.model, state: call.state, questions: call.questions });
  let result = null;
  let error = null;
  try {
    result = await recorder.runInDecide(handle.decide_seq, () =>
      neurolink.decide({ provider: call.provider, model: call.model, state: call.state, questions: call.questions, timeoutMs: call.timeoutMs ?? 20000 }),
    );
  } catch (e) {
    error = recorder.describeError(e);
  }
  recorder.writeDecide(handle, {
    kit_request_text: kitRequest,
    decide_call: { provider: call.provider, model: call.model ?? null, timeoutMs: call.timeoutMs ?? 20000 },
    decide_result: result,
    decide_error: error,
    kit_response_status: error ? 502 : 200,
    kit_response_text: JSON.stringify(error ? { detail: error.message } : { model: result.model, answers: result.answers, usage: result.usage }),
  });
  process.stdout.write(`${JSON.stringify({ i, decide_seq: handle.decide_seq, ok: error === null, kind: error?.kind ?? null })}\n`);
  if (plan.crashAfter === i + 1) throw new Error("planned crash");
}
process.exit(0);

import math

import pytest

from decision_index import constants as C
from decision_index.scoring import index as I


def make(n, raw, random, coverage=1.0, tracks=None):
    tracks = tracks or [dict(track="all", raw=raw, random=random, skill=I.skill(raw, random), planned_cases=10, coverage=coverage, pending=0.0, label_universe=[])]
    return dict(catalog_id=n, raw=sum(t["raw"] for t in tracks) / len(tracks), skill=sum(t["skill"] for t in tracks) / len(tracks), coverage=sum(t["coverage"] for t in tracks) / len(tracks), pending=0.0, tracks=tracks)


def panel_scored(value=0.6, random=0.2):
    scored = {n: make(n, value, random) for n in I.panel_ids() if n not in C.INTERACTIVE}
    for n in C.INTERACTIVE:
        scored[n] = I.interactive_placeholder(n)
    return scored


def test_area_membership():
    areas = {a["id"]: a["ids"] for a in I.area_ids()}
    assert areas == {"knowledge": [24, 25, 30, 43, 44, 31], "language": [11, 40, 41], "retrieval": [36, 37], "tools": [1, 2, 6], "arts": [20, 21, 22, 23, 50]}
    assert sum(len(v) for v in areas.values()) == 19


def test_uniform_skill_reproduces_proposal_examples():
    scored = panel_scored(0.6, 0.0)
    scores, cats = I.recompute(scored)
    assert scores["balanced_skill"] == pytest.approx(60.0)
    assert scores["breadth_skill"] == pytest.approx(60.0)
    assert len(cats) == 5


def test_uneven_breadth_matches_proposal():
    values = [0.9, 0.9, 0.9, 0.2, 0.1]
    breadth = 100 * (math.prod((0.1 + 0.9 * x) ** 0.2 for x in values) - 0.1) / 0.9
    assert breadth == pytest.approx(47.28240846043158)


def test_coverage_adjustment_unanswered_counts_as_wrong():
    scored = panel_scored(0.6, 0.2)
    scored[24] = make(24, 0.3, 0.25, coverage=0.5)
    scores, cats = I.recompute(scored)
    knowledge = next(c for c in cats if c["id"] == "knowledge")
    assert knowledge["coverage"] == pytest.approx((0.5 + 5) / 6)
    assert scores["balanced_skill"] < 50.0


def test_headline_track_replaces_isarcasm():
    scored = panel_scored(0.6, 0.2)
    tracks = [dict(track="iSarcasmEval-A-Ar", raw=0.2, random=0.2, skill=0.0, planned_cases=1, coverage=1.0, pending=0.0, label_universe=[]), dict(track="iSarcasmEval-A-En", raw=0.7, random=0.2227, skill=I.skill(0.7, 0.2227), planned_cases=1, coverage=1.0, pending=0.0, label_universe=[]), dict(track="iSarcasmEval-C-En", raw=0.9, random=0.5, skill=0.8, planned_cases=1, coverage=1.0, pending=0.0, label_universe=[])]
    scored[40] = make(40, 0.0, 0.0, tracks=tracks)
    entry = I.index_entry(scored)
    b = entry["benchmarks"]["40"]
    assert b["raw"] == pytest.approx(0.7)
    assert b["random"] == pytest.approx(0.2227)
    assert b["skill"] == pytest.approx(round((0.7 - 0.2227) / (1 - 0.2227), 4))
    assert [t["track"] for t in b["tracks"]] == ["A · Arabic", "A · English", "C · English pairs"]
    assert [t["headline"] for t in b["tracks"]] == [False, True, False]


def test_interactive_dropped_from_index_but_zero_in_frozen_panel():
    scored = panel_scored(1.0, 0.0)
    entry = I.index_entry(scored)
    assert entry["index"] == pytest.approx(100.0)
    frozen = entry["frozen_panel"]["scores"]["balanced_skill"]
    assert frozen == pytest.approx(100 * (1 + 1 + 1 + 3 / 5 + 1 / 5) / 5, abs=0.01)
    assert all(not entry["benchmarks"][str(n)]["in_index"] for n in C.INTERACTIVE)


def test_static_score_accuracy_with_unanswered_rows():
    rows = []
    res = {}
    for i in range(4):
        rid = f"44:CLadder:CLadder:balanced:{i}"
        rows.append({"_evaluation": {"run_id": rid, "catalog_id": 44, "group_id": f"g{i}", "track": "CLadder"}, "questions": {"q1": {"type": "choice", "instructions": "", "criteria": {"A": "yes", "B": "no"}}}, "expected": {"q1": "A"}})
        if i < 3:
            res[rid] = {"status": "ok", "answers": {"q1": {"type": "choice", "choice": "A" if i < 2 else "B", "probabilities": {"A": 0.5, "B": 0.5}}}}
    res["44:CLadder:CLadder:balanced:3"] = {"status": "unsupported", "answers": {}}
    out = I.static_score(44, rows, res, I.chance_baselines())
    assert out["raw"] == pytest.approx(0.5)
    assert out["coverage"] == pytest.approx(0.75)
    assert out["tracks"][0]["random"] == pytest.approx(0.5)
    assert out["skill"] == 0.0


def test_static_score_conservative_f1_track():
    rows = []
    res = {}
    for i, gold in enumerate(["yes", "no", "yes"]):
        rid = f"40:iSarcasmEval-A-En:iSarcasmEval-A-En:test:{i}"
        rows.append({"_evaluation": {"run_id": rid, "catalog_id": 40, "group_id": f"g{i}", "track": "iSarcasmEval-A-En"}, "questions": {"sarcastic": {"type": "choice", "instructions": "", "criteria": {"no": "No", "yes": "Yes"}}}, "expected": {"sarcastic": gold}})
        if i < 2:
            res[rid] = {"status": "ok", "answers": {"sarcastic": {"type": "choice", "choice": "yes", "probabilities": {"yes": 1.0, "no": 0.0}}}}
    out = I.static_score(40, rows, res, I.chance_baselines())
    t = out["tracks"][0]
    assert t["track"] == "iSarcasmEval-A-En"
    assert t["raw"] == pytest.approx(2 * 1 / (2 * 1 + 1 + 0 + 1))
    assert t["random"] == pytest.approx(0.2226862339379383)
    assert t["coverage"] == pytest.approx(2 / 3)

